PROGRAM motor_interlock
VAR_INPUT
    Start : BOOL;
    Stop : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    Motor : BOOL;
END_VAR

VAR
    MotorLatch : BOOL;
    EStopTimer : TON;
END_VAR

MotorLatch := FALSE;

EStopTimer(IN := NOT EStop, PT := T#0s);

IF EStop THEN
    MotorLatch := FALSE;
    Motor := FALSE;
ELSIF Start AND NOT Stop AND NOT MotorLatch THEN
    MotorLatch := TRUE;
    Motor := TRUE;
ELSIF Stop THEN
    MotorLatch := FALSE;
    Motor := FALSE;
END_IF;

IF EStopTimer.Q THEN
    MotorLatch := FALSE;
    Motor := FALSE;
END_IF;
END_PROGRAM

