PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    LowLimit : INT := 10;
    HighLimit : INT := 90;
    PumpTimer : TON;
END_VAR

PumpTimer(IN := PumpIn, PT := T#0s);

IF Level <= LowLimit THEN
    PumpIn := TRUE;
    ValveOut := FALSE;
ELSIF Level >= HighLimit THEN
    PumpIn := FALSE;
    ValveOut := TRUE;
ELSE
    PumpIn := FALSE;
    ValveOut := FALSE;
END_IF;

// Safety condition: Prevent pump from running when level is at or above high limit
IF Level >= HighLimit AND PumpIn THEN
    PumpIn := FALSE;
END_IF;

END_PROGRAM

PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    PumpInTimer : TON;
    ValveOutTimer : TON;
END_VAR

// Reset timers on each cycle
PumpInTimer(IN := FALSE);
ValveOutTimer(IN := FALSE);

// Check if level is at or above high limit
IF Level >= 90 THEN
    // Turn off pump and open valve
    PumpIn := FALSE;
    ValveOut := TRUE;
    // Set timer for safety
    ValveOutTimer(IN := TRUE, PT := T#5s);
ELSIF Level <= 10 THEN
    // Turn on pump and close valve
    PumpIn := TRUE;
    ValveOut := FALSE;
ELSE
    // Maintain current state
    PumpIn := FALSE;
    ValveOut := FALSE;
END_IF;

// Prevent pump from running when level is at or above high limit
IF Level >= 90 AND PumpInTimer.Q THEN
    PumpIn := FALSE;
END_IF;

END_PROGRAM

