        TimerB(IN := TRUE, PT := T#0s);
    END_IF;
    IF TimerB.Q THEN
        DoorA := FALSE;
        DoorB := TRUE;
    END_IF;
ELSE
    DoorA := FALSE;
    DoorB := FALSE;
END_IF;

LastOpenA_Cmd := OpenA_Cmd;
LastOpenB_Cmd := OpenB_Cmd;

END_PROGRAM

