PROGRAM intersection
VAR
    State : INT;
    NS_G, NS_Y, NS_R : BOOL;
    EW_G, EW_Y, EW_R : BOOL;
    TNSGreen, TEWGreen : TON;
    TNSYellow, TEWYellow : TON;
    TAllRed : TON;
END_VAR

State := State + 1;
IF State > 5 THEN
    State := 0;
END_IF;

CASE State OF
    0:
        NS_G := TRUE;
        NS_Y := FALSE;
        NS_R := FALSE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
        TNSGreen(IN := TRUE, PT := T#2s);
        TEWGreen(IN := FALSE, PT := T#0s);
        TNSYellow(IN := FALSE, PT := T#0s);
        TEWYellow(IN := FALSE, PT := T#0s);
        TAllRed(IN := FALSE, PT := T#0s);
    1:
        NS_G := FALSE;
        NS_Y := TRUE;
        NS_R := FALSE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
        TNSGreen(IN := FALSE, PT := T#0s);
        TEWGreen(IN := FALSE, PT := T#0s);
        TNSYellow(IN := TRUE, PT := T#1s);
        TEWYellow(IN := FALSE, PT := T#0s);
        TAllRed(IN := FALSE, PT := T#0s);
    2:
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
        TNSGreen(IN := FALSE, PT := T#0s);
        TEWGreen(IN := FALSE, PT := T#0s);
        TNSYellow(IN := FALSE, PT := T#0s);
        TEWYellow(IN := FALSE, PT := T#0s);
        TAllRed(IN := TRUE, PT := T#1s);
    3:
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := TRUE;
        EW_Y := FALSE;
        EW_R := FALSE;
        TNSGreen(IN := FALSE, PT := T#0s);
        TEWGreen(IN := TRUE, PT := T#2s);
        TNSYellow(IN := FALSE, PT := T#0s);
        TEWYellow(IN := FALSE, PT := T#0s);
        TAllRed(IN := FALSE, PT := T#0s);
    4:
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := FALSE;
        EW_Y := TRUE;
        EW_R := FALSE;
        TNSGreen(IN := FALSE, PT := T#0s);
        TEWGreen(IN := FALSE, PT := T#0s);
        TNSYellow(IN := FALSE, PT := T#0s);
        TEWYellow(IN := TRUE, PT := T#1s);
        TAllRed(IN := FALSE, PT := T#0s);
    5:
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
        TNSGreen(IN := FALSE, PT := T#0s);
        TEWGreen(IN := FALSE, PT := T#0s);
        TNSYellow(IN := FALSE, PT := T#0s);
        TEWYellow(IN := FALSE, PT := T#0s);
        TAllRed(IN := TRUE, PT := T#1s);
END_CASE;

IF State IN {0, 3} THEN
    NS_G := TNSGreen.Q;
    NS_Y := TNSYellow.Q;
    NS_R := NOT TNSGreen.Q AND NOT TNSYellow.Q;
    EW_G := FALSE;
    EW_Y := FALSE;
    EW_R := TRUE;
ELSIF State IN {1, 4} THEN
    NS_G := FALSE;
    NS_Y := TNSYellow.Q;
    NS_R := NOT TNSYellow.Q AND NOT TNSGreen.Q;
    EW_G := FALSE;
    EW_Y := FALSE;
    EW_R := TRUE;
ELSIF State IN {2, 5} THEN
    NS_G := FALSE;
    NS_Y := FALSE;
    NS_R := TRUE;
    EW_G := FALSE;
    EW_Y := FALSE;
    EW_R := TRUE;
END_IF;
END_PROGRAM

PROGRAM intersection
VAR
    NS_G, NS_Y, NS_R, EW_G, EW_Y, EW_R : BOOL;
    State : INT := 0;
    TON_NS_G, TON_NS_Y, TON_NS_R, TON_EW_G, TON_EW_Y, TON_EW_R : TON;
    PT_GREEN, PT_YELLOW, PT_ALLRED : TIME := T#2s, T#1s, T#1s;
END_VAR

TON_NS_G(IN := NOT (State = 0 OR State = 3 OR State = 5), PT := PT_GREEN);
TON_NS_Y(IN := NOT (State = 0 OR State = 3 OR State = 5), PT := PT_YELLOW);
TON_NS_R(IN := NOT (State = 0 OR State = 3 OR State = 5), PT := PT_ALLRED);

TON_EW_G(IN := NOT (State = 1 OR State = 4 OR State = 5), PT := PT_GREEN);
TON_EW_Y(IN := NOT (State = 1 OR State = 4 OR State = 5), PT := PT_YELLOW);
TON_EW_R(IN := NOT (State = 1 OR State = 4 OR State = 5), PT := PT_ALLRED);

NS_G := TON_NS_G.Q;
NS_Y := TON_NS_Y.Q;
NS_R := TON_NS_R.Q;

EW_G := TON_EW_G.Q;
EW_Y := TON_EW_Y.Q;
EW_R := TON_EW_R.Q;

CASE State OF
    0: 
        TON_NS_G(IN := TRUE, PT := PT_GREEN);
        TON_NS_Y(IN := FALSE, PT := PT_YELLOW);
        TON_NS_R(IN := FALSE, PT := PT_ALLRED);
        TON_EW_G(IN := FALSE, PT := PT_GREEN);
        TON_EW_Y(IN := FALSE, PT := PT_YELLOW);
        TON_EW_R(IN := TRUE, PT := PT_ALLRED);
    1: 
        TON_NS_G(IN := FALSE, PT := PT_GREEN);
        TON_NS_Y(IN := TRUE, PT := PT_YELLOW);
        TON_NS_R(IN := FALSE, PT := PT_ALLRED);
        TON_EW_G(IN := FALSE, PT := PT_GREEN);
        TON_EW_Y(IN := FALSE, PT := PT_YELLOW);
        TON_EW_R(IN := TRUE, PT := PT_ALLRED);
    2: 
        TON_NS_G(IN := FALSE, PT := PT_GREEN);
        TON_NS_Y(IN := FALSE, PT := PT_YELLOW);
        TON_NS_R(IN := TRUE, PT := PT_ALLRED);
        TON_EW_G(IN := FALSE, PT := PT_GREEN);
        TON_EW_Y(IN := FALSE, PT := PT_YELLOW);
        TON_EW_R(IN := TRUE, PT := PT_ALLRED);
    3: 
        TON_NS_G(IN := FALSE, PT := PT_GREEN);
        TON_NS_Y(IN := FALSE, PT := PT_YELLOW);
        TON_NS_R(IN := TRUE, PT := PT_ALLRED);
        TON_EW_G(IN := TRUE, PT := PT_GREEN);
        TON_EW_Y(IN := FALSE, PT := PT_YELLOW);
        TON_EW_R(IN := FALSE, PT := PT_ALLRED);
    4: 
        TON_NS_G(IN := FALSE, PT := PT_GREEN);
        TON_NS_Y(IN := FALSE, PT := PT_YELLOW);
        TON_NS_R(IN := TRUE, PT := PT_ALLRED);
        TON_EW_G(IN := FALSE, PT := PT_GREEN);
        TON_EW_Y(IN := TRUE, PT := PT_YELLOW);
        TON_EW_R(IN := FALSE, PT := PT_ALLRED);
    5: 
        TON_NS_G(IN := FALSE, PT := PT_GREEN);
        TON_NS_Y(IN := FALSE, PT := PT_YELLOW);
        TON_NS_R(IN := TRUE, PT := PT_ALLRED);
        TON_EW_G(IN := FALSE, PT := PT_GREEN);
        TON_EW_Y(IN := FALSE, PT := PT_YELLOW);
        TON_EW_R(IN := TRUE, PT := PT_ALLRED);
END_CASE;

IF TON_NS_G.Q THEN State := 0; ELSIF TON_NS_Y.Q THEN State := 1; ELSIF TON_NS_R.Q THEN State := 2; END_IF;
IF TON_EW_G.Q THEN State := 3; ELSIF TON_EW_Y.Q THEN State := 4; ELSIF TON_EW_R.Q THEN State := 5; END_IF;

END_PROGRAM

PROGRAM intersection
