PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR

VAR
    State : INT := 0;
    T_Fill : TON;
    T_React : TON;
    LIQ_MIN : INT := 10;
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
END_VAR

T_Fill(IN := FillValve AND Level < LVL_HIGH);
T_React(IN := Heater AND Agitator AND Level >= LIQ_MIN);

IF EStop THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
ELSIF NOT EStop THEN
    CASE State OF
        0:
            IF StartBatch THEN
                State := 1;
            END_IF;
        1:
            IF Level >= LVL_HIGH THEN
                State := 2;
            END_IF;
        2:
            IF Temp >= TEMP_SET AND Level >= LIQ_MIN THEN
                State := 3;
            END_IF;
        3:
            IF T_React.Q THEN
                State := 4;
            END_IF;
        4:
            IF Level <= LVL_LOW THEN
                State := 0;
            END_IF;
    END_CASE;
END_IF;

FillValve := (State = 1) AND (NOT DrainValve);
Heater := (State = 2) OR (State = 3);
Agitator := (State = 2) OR (State = 3);
DrainValve := (State = 4) AND (NOT FillValve);

END_PROGRAM

