        Pump := TRUE;
        Valve := FALSE;
        IF Level >= HighLevel OR EStop THEN
            State := 2;
        END_IF;

    2: // Draining
        Pump := FALSE;
        Valve := TRUE;
        IF Level <= LowLevel OR EStop THEN
            State := 0;
        END_IF;
END_CASE;

// Safety conditions
IF Pump AND Valve THEN
    Pump := FALSE;
    Valve := FALSE;
END_IF;

IF Level >= HighLevel THEN
    Pump := FALSE;
END_IF;

IF Level <= LowLevel THEN
    Valve := FALSE;
END_IF;

