    // Starting state, wait for PT_SEQ ticks
    C1 := FALSE;
    C2 := TRUE;
    State := 2;
ELSIF State = 2 THEN
    // Both conveyors running
    C1 := TRUE;
    C2 := TRUE;
END_IF;

// Handle transitions based on timer
T1(IN := TRUE, PT := T#2s);

END_PROGRAM

