        PurgeTimer(IN := TRUE, PT := T#3s);
        IF NOT PurgeTimer.Q THEN
            State := 2;
        END_IF;
        Fan := TRUE;
        Fuel := FALSE;
        Ignition := FALSE;

    2: // Ignition Trial
        IgnitionTimer(IN := TRUE, PT := T#2s);
        IF IgnitionTimer.Q THEN
            IF Flame THEN
                State := 3;
            ELSE
                State := 0;
            END_IF;
        END_IF;
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := TRUE;

    3: // Run
        IF NOT Flame OR StopPB OR NOT EStop THEN
            State := 0;
        END_IF;
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := FALSE;
END_CASE

// Safety conditions
IF Fuel AND NOT Fan THEN
    // Violation: Fuel valve open without fan
    State := 0;
END_IF

IF Ignition AND NOT Fuel THEN
    // Violation: Igniter on without fuel
    State := 0;
END_IF
END_PROGRAM

