PROGRAM pump_alt
VAR_INPUT
    Demand : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    Pump1 : BOOL;
    Pump2 : BOOL;
END_VAR

VAR
    Lead : INT := 0;
    PrevDemand : BOOL := FALSE;
    LeadChangeTimer : TON;
END_VAR

LeadChangeTimer(IN := NOT PrevDemand AND Demand, PT := T#1s);

IF EStop THEN
    Pump1 := FALSE;
    Pump2 := FALSE;
    Lead := 0;
    PrevDemand := FALSE;
ELSIF Demand THEN
    IF LeadChangeTimer.Q THEN
        Lead := 1 - Lead;
        LeadChangeTimer(IN := FALSE);
    END_IF;
    CASE Lead OF
        0: Pump1 := TRUE; Pump2 := FALSE;
        1: Pump1 := FALSE; Pump2 := TRUE;
    ELSE
        Pump1 := FALSE; Pump2 := FALSE;
    END_CASE;
END_IF;

PrevDemand := Demand;
END_PROGRAM

PROGRAM pump_alt
VAR_INPUT
    Demand : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    Pump1 : BOOL;
    Pump2 : BOOL;
END_VAR

VAR
    Lead : INT := 0;
    PrevDemand : BOOL := FALSE;
    DemandTimer : TON;
END_VAR

// Update Previous Demand State
PrevDemand := Demand;

// Check for Demand End (Falling Edge)
IF NOT Demand AND PrevDemand THEN
    // Alternate Lead
    Lead := 1 - Lead;
END_IF

// Ensure Pumps Do Not Run Simultaneously
Pump1 := FALSE;
Pump2 := FALSE;

// Check for EStop Condition
IF EStop THEN
    // Both Pumps Stop if EStop is Active
    Pump1 := FALSE;
    Pump2 := FALSE;
ELSE
    // Assign Pumps Based on Lead State and Demand
    IF Demand THEN
        CASE Lead OF
            0:
                Pump1 := TRUE;
            1:
                Pump2 := TRUE;
        END_CASE;
    END_IF;
END_IF

// Reset Demand Timer if Demand Ends
IF NOT Demand THEN
    DemandTimer(IN := TRUE, PT := T#0s);
END_IF

END_PROGRAM

