        PumpsRunning := FALSE;
        Lead := 1 - Lead;
    END_IF;

    Pump1 := NOT EStop AND Lead = 0 AND Demand AND P1Timer.Q;
    Pump2 := NOT EStop AND Lead = 1 AND Demand AND P2Timer.Q;

