PrevDemand := Demand;

IF NOT(EStop) THEN
    IF Demand AND NOT(PrevDemand) THEN
        Lead := 1 - Lead; // Toggle lead on rising edge of demand
    END_IF;

    Pump1 := (NOT(EStop) AND Demand AND (Lead = 0)) AND NOT(Pump2_TON.Q);
    Pump2 := (NOT(EStop) AND Demand AND (Lead = 1)) AND NOT(Pump1_TON.Q);
